def tr(lang: str | None, key: str, **params: object) -> str:
    """Translate ``key`` into ``lang`` (``pt`` default) filling ``{placeholders}``."""
    entry = _MESSAGES.get(key)
    if entry is None:
        return key
    text = entry.get(lang or "pt") or entry["pt"]
    return text.format(**params) if params else text


def lang_of(params: dict | None) -> str:
    """Extract ``lang`` from query-string params or a JSON body."""
    raw = (params or {}).get("lang")
    if isinstance(raw, list):
        raw = raw[0] if raw else None
    return "en" if raw == "en" else "pt"
